<script setup lang="ts">
/**
 * Toast.Card: one toast in the viewport, with its timer, its dismissal and its exit.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import {
  Icon,
  TOAST_TONE_ICON,
  composingKey,
  focusAfterToast,
  removeToast,
  toast,
  type ToastRecord,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/toast.module.css'
import Button from '../controls/Button.vue'

export interface ToastCardProps {
  record: ToastRecord
  /**
   * The close button’s accessible name.
   */
  dismissLabel: string
  /**
   * The reader is on the list, so the timer waits.
   */
  paused: boolean
}

defineOptions({ name: 'ToastCard', inheritAttrs: false })

const props = defineProps<ToastCardProps>()
const swipe = ref('')
const tracking = ref(false)
const startX = ref(0)
const deltaX = ref(0)
const card = useTemplateRef<HTMLElement>('card')
const icon = computed(() =>
  props.record.tone === 'neutral' ? null : TOAST_TONE_ICON[props.record.tone],
)
const dismissible = computed(() => props.record.dismissible !== false)
const dismiss = computed(() => (): void => {
  if (dismissible.value) toast.dismiss(props.record.id)
})
const act = computed(() => (): void => {
  props.record.action?.onClick()
  toast.dismiss(props.record.id)
})
const press = computed(() => (event: PointerEvent): void => {
  if (
    !dismissible.value ||
    event.button !== 0 ||
    (event.target as Element).closest('button') !== null
  )
    return
  tracking.value = true
  startX.value = event.clientX
  deltaX.value = 0
})
const drag = computed(() => (event: PointerEvent): void => {
  if (!tracking.value) return
  deltaX.value = Math.max(0, event.clientX - startX.value)
  if (deltaX.value > 0) swipe.value = 'move'
})
const lift = computed(() => (): void => {
  if (!tracking.value) return
  tracking.value = false
  if (swipe.value !== 'move') return
  if (deltaX.value > 50) {
    swipe.value = 'end'
    dismiss.value()
  } else {
    swipe.value = 'cancel'
    deltaX.value = 0
  }
})
const present = usePresence(() => props.record.closing !== true, card, 'toast.enter')
const effect1 = () => {
  props.record.closing === true && focusAfterToast(card.value)
}
watch(() => props.record.closing, effect1, { flush: 'post' })
const effect2 = () => {
  present.value || removeToast(props.record.id)
}
watch(() => present.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const timer = setTimeout(
    () => {
      !props.paused &&
        props.record.closing !== true &&
        dismissible.value &&
        Number.isFinite(props.record.durationMs) &&
        toast.dismiss(props.record.id)
    },
    Number.isFinite(props.record.durationMs) ? props.record.durationMs : 0,
  )
  release3 = () => clearTimeout(timer)
}
onMounted(effect3)
watch(() => [props.record.revision, props.paused, props.record.closing], effect3, { flush: 'post' })
onBeforeUnmount(() => release3?.())
</script>

<template>
  <li
    ref="card"
    :class="styles.toast"
    :style="{
      '--radix-toast-swipe-move-x': `${deltaX}px`,
      '--radix-toast-swipe-end-x': `${deltaX}px`,
    }"
    tabindex="0"
    :data-tone="record.tone"
    :data-state="record.closing === true ? 'closed' : 'open'"
    :data-swipe="swipe === '' ? undefined : swipe"
    data-swipe-direction="right"
    data-member="toast"
    @keydown="
      $event.key === 'Escape' &&
      !$event.defaultPrevented &&
      !composingKey($event) &&
      ($event.preventDefault(), dismiss())
    "
    @pointerdown="press($event)"
    @pointermove="drag($event)"
    @pointerup="lift()"
    @pointercancel="lift()"
  >
    <!-- wait -->
    <span v-if="record.loading === true" :class="[styles.tone, styles.wait]" aria-hidden="true">
      <Icon name="loading" />
    </span>
    <!-- tone -->
    <span v-else-if="icon !== null" :class="styles.tone">
      <Icon :name="icon" />
    </span>
    <!-- text -->
    <div :class="styles.text">
      <!-- title -->
      <div :class="styles.title" data-toast-title="">
        {{ record.title }}
      </div>
      <!-- description -->
      <div v-if="record.description !== undefined" :class="styles.description">
        {{ record.description }}
      </div>
      <!-- content -->
      <div v-if="record.content !== undefined" :class="styles.content" data-toast-content="">
        <component :is="record.content" />
      </div>
    </div>
    <!-- action -->
    <div v-if="record.action !== undefined" :class="styles.action">
      <Button
        variant="ghost"
        :tone="record.tone === 'danger' ? 'danger' : 'accent'"
        size="sm"
        :label="record.action?.label ?? ''"
        @click="act()"
      />
    </div>
    <!-- close -->
    <div v-if="dismissible" :class="styles.close">
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="close"
        :label="dismissLabel"
        @click="dismiss()"
      />
    </div>
  </li>
</template>
